'use strict';

const express = require('express');

const app = express();

// Exported so tests can assert cleanup on client disconnect.
let activeClients = 0;

const TICK_MS = 200;      // price tick interval
const HEARTBEAT_MS = 1000; // SSE comment heartbeat interval

function randomWalk(price) {
  // Small multiplicative random walk, clamped to stay positive.
  const next = price * (1 + (Math.random() - 0.5) * 0.01);
  return Math.max(0.01, Number(next.toFixed(2)));
}

app.get('/ticker', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
  });
  res.write('retry: 1000\n\n');

  activeClients += 1;

  let price = 100;
  const symbol = String(req.query.symbol || 'MKT').toUpperCase();

  const tick = setInterval(() => {
    price = randomWalk(price);
    res.write(
      `event: price\ndata: ${JSON.stringify({ symbol, price })}\n\n`
    );
  }, TICK_MS);

  const heartbeat = setInterval(() => {
    res.write(':heartbeat\n\n');
  }, HEARTBEAT_MS);

  const cleanup = () => {
    clearInterval(tick);
    clearInterval(heartbeat);
    activeClients -= 1;
  };

  // Fires on client disconnect (and normal response end).
  req.on('close', cleanup);
});

let server;
if (require.main === module) {
  const port = Number(process.env.PORT || 3000);
  server = app.listen(port, () => {
    console.log(`ticker listening on http://localhost:${port}/ticker`);
  });
}

module.exports = { app, get activeClients() { return activeClients; } };

