'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');

const { app, activeClients } = require('./server.js');

function startServer() {
  return new Promise((resolve) => {
    const server = app.listen(0, '127.0.0.1', () => resolve(server));
  });
}

function get(server, path) {
  const { port } = server.address();
  return new Promise((resolve, reject) => {
    http
      .get({ host: '127.0.0.1', port, path }, resolve)
      .on('error', reject);
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

test('GET /ticker streams price events and heartbeats, and cleans up on disconnect', async (t) => {
  const server = await startServer();
  t.after(() => new Promise((r) => server.close(r)));

  assert.equal(activeClients, 0, 'no clients before connect');

  const res = await get(server, '/ticker?symbol=AAPL');
  assert.equal(res.statusCode, 200);
  assert.match(res.headers['content-type'], /text\/event-stream/);

  let raw = '';
  res.setEncoding('utf8');
  res.on('data', (chunk) => { raw += chunk; });

  // Give it a bit more than 2 seconds to accumulate ticks + heartbeats.
  await sleep(2300);

  // At ~5 ticks/sec over ~2.3s we expect >= 10 data lines.
  const dataLines = raw.split('\n').filter((l) => l.startsWith('data: '));
  assert.ok(
    dataLines.length >= 10,
    `expected >= 10 data lines, got ${dataLines.length}`
  );
  for (const line of dataLines.slice(0, 3)) {
    const payload = JSON.parse(line.slice('data: '.length));
    assert.equal(payload.symbol, 'AAPL');
    assert.equal(typeof payload.price, 'number');
    assert.ok(payload.price > 0);
  }

  // At 1 heartbeat/sec over ~2.3s we expect >= 2 heartbeat comments.
  const heartbeats = raw.split('\n').filter((l) => l.startsWith(':heartbeat'));
  assert.ok(
    heartbeats.length >= 2,
    `expected >= 2 heartbeats, got ${heartbeats.length}`
  );

  // Client disconnect: destroy the socket.
  res.destroy();
  await sleep(300);

  assert.equal(
    activeClients,
    0,
    'activeClients must return to 0 after disconnect (no interval leak)'
  );

  server.close();
});

